package Practice;

public class Arithmetic {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int a=20;
		int b=10;
		
		System.out.println(a+b);  // + is arithemtic operator
		System.out.println(a-b);  // - is arthm oprtr
		System.out.println(a*b);  // * is arth opertr
		System.out.println(a/b);  // / is arth oprtr
		System.out.println(a%b);  // % is arthm oprtr
		
		// +,-,*,/,% are arithemtic operators
	}

}
